FUNCTION_BLOCK FB_PortAGV_LinkspanMotionComp
(*
 * ====================================================================================================
 * SYSTEM IDENTIFIER  : FB_PortAGV_LinkspanMotionComp
 * CLASSIFICATION     : Heavy Autonomous Guided Vehicle (AGV) & Shore-to-Ship Cyber-Physical Interface
 * TARGET DOMAIN      : Automated Port AGV Ferry Embarkation: Linkspan Ramp Dynamic Motion Compensation
 *                      and Traction Wheel Torque Vectoring Architecture
 * DESIGN STANDARDS   : IEC 61131-3 3rd Ed., IEC 61508 SIL-3, ISO 26262 ASIL-D, DNVGL-ST-0054, PIANC WG 158
 * CONTROL TOPOLOGY   : Multivariable Model Predictive Control (MPC) with Dynamic State-Space Observer,
 *                      2oo3 Triple Modular Redundancy (TMR) Voting, 4-Corner Dynamic Normal Load Transfer,
 *                      Active Traction Wheel Slip Ratio Regulation, and Hydraulic Ramp Heave Feedforward
 * KINEMATICS         : 6-DOF Wave Motion Coupling (Linkspan Longitudinal Pitch, Transverse Roll, Vessel Heave)
 * TIRE ADHESION      : Dynamic Non-linear Dugoff/Burckhardt Friction Formulations for Wet Steel & Composite Decks
 * ====================================================================================================
 *)

VAR_INPUT
    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: LINKSPAN LONGITUDINAL PITCH SENSORS [deg] --- *)
    rRampPitch_Deg_A            : REAL;     (* Linkspan Inclinometer Transducer Channel-A [deg] *)
    rRampPitch_Deg_B            : REAL;     (* Linkspan Inclinometer Transducer Channel-B [deg] *)
    rRampPitch_Deg_C            : REAL;     (* Linkspan Inclinometer Transducer Channel-C [deg] *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: SHIP-SHORE INTERFACE RELATIVE HEAVE TELEMETRY [m] --- *)
    rFerryHeaveDisp_M_A         : REAL;     (* Stern Ramp Relative Laser/Radar Heave Displacement Ch-A [m] *)
    rFerryHeaveDisp_M_B         : REAL;     (* Stern Ramp Relative Laser/Radar Heave Displacement Ch-B [m] *)
    rFerryHeaveDisp_M_C         : REAL;     (* Stern Ramp Relative Laser/Radar Heave Displacement Ch-C [m] *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: LINKSPAN FINGER FLAP BEARING HINGE PIN LOADCELLS [kN] --- *)
    rFlapBearingLoad_kN_A       : REAL;     (* Finger Flap Dynamic Hinge Reaction Pin Loadcell Ch-A [kN] *)
    rFlapBearingLoad_kN_B       : REAL;     (* Finger Flap Dynamic Hinge Reaction Pin Loadcell Ch-B [kN] *)
    rFlapBearingLoad_kN_C       : REAL;     (* Finger Flap Dynamic Hinge Reaction Pin Loadcell Ch-C [kN] *)

    (* --- AGV ONBOARD VEHICLE DYNAMICS & INERTIAL MEASUREMENT SENSORS --- *)
    rAGV_LongitudinalVelocity_mps : REAL;   (* Vehicle Longitudinal Doppler Radar Ground Speed [m/s] *)
    rAGV_GrossVehicleWeight_Ton   : REAL;   (* Total Vehicle Tare + Container Payload Mass [ton] *)
    rRampRoll_Deg               : REAL;     (* Linkspan Transverse Cross-Tilt Inclinometer Angle [deg] *)
    rAGV_SteeringAngle_Deg      : REAL;     (* Virtual Kingpin Articulated Front Axle Steer Angle [deg] *)

    (* --- INDEPENDENT 4-CORNER DRIVE WHEEL SURFACE VELOCITIES [m/s] --- *)
    rWheelSpeed_FL_mps          : REAL;     (* Front-Left Drive Wheel Surface Linear Speed [m/s] *)
    rWheelSpeed_FR_mps          : REAL;     (* Front-Right Drive Wheel Surface Linear Speed [m/s] *)
    rWheelSpeed_RL_mps          : REAL;     (* Rear-Left Drive Wheel Surface Linear Speed [m/s] *)
    rWheelSpeed_RR_mps          : REAL;     (* Rear-Right Drive Wheel Surface Linear Speed [m/s] *)

    (* --- SUPERVISORY COMMANDS, TRAJECTORY TARGETS & SAFETY ENABLES --- *)
    bMasterEnable               : BOOL;     (* Embarkation Automation Master Operational Authorization *)
    bEmergencyStop              : BOOL;     (* Safety PLC Cat-4 / SIL-3 Hardwired Active-Low Emergency Stop Loop *)
    rTargetVelocity_mps         : REAL;     (* Fleet Supervisory Central Route Speed Setpoint [m/s] *)
    rCycleTimeSec               : REAL;     (* Deterministic PLC Periodic Scan Execution Delta-T [s] *)
END_VAR

VAR_OUTPUT
    (* --- 4-WHEEL INDEPENDENT ELECTRIC INVERTER TORQUE DEMANDS [kNm] --- *)
    rTorqueDemand_FL_kNm        : REAL;     (* Front-Left Drive Hub Motor Electromagnetic Torque Demand [kNm] *)
    rTorqueDemand_FR_kNm        : REAL;     (* Front-Right Drive Hub Motor Electromagnetic Torque Demand [kNm] *)
    rTorqueDemand_RL_kNm        : REAL;     (* Rear-Left Drive Hub Motor Electromagnetic Torque Demand [kNm] *)
    rTorqueDemand_RR_kNm        : REAL;     (* Rear-Right Drive Hub Motor Electromagnetic Torque Demand [kNm] *)

    (* --- LINKSPAN HYDRAULIC MOTION COMPENSATION CYLINDER DEMANDS --- *)
    rHydraulicCylFlowDemand_Pct : REAL;     (* Ramp Active Heave Compensation Proportional Servo Valve Spool [%] *)
    rHydraulicCylPressDemand_bar: REAL;     (* Dynamic Counter-Balancing Cylinder Cylinder Pressure Setpoint [bar] *)

    (* --- DIAGNOSTIC, SAFETY INTEGRITY & SYSTEM STATUS ENUNCIATORS --- *)
    wSystemStatusWord           : WORD;     (* Operation Mode, Redundancy Tier & State Machine Index [HEX] *)
    wAlarmWord                  : WORD;     (* ISA-18.2 Categorized Diagnostic Alarm Bitfield [HEX] *)
    rVotedRampPitch_Deg         : REAL;     (* 2oo3 TMR Validated Linkspan Longitudinal Incline [deg] *)
    rVotedHeaveDisp_M           : REAL;     (* 2oo3 TMR Validated Vessel Deck Relative Heave Displacement [m] *)
    rVotedFlapLoad_kN           : REAL;     (* 2oo3 TMR Validated Ramp Finger Flap Reaction Load [kN] *)
    rEstimatedFrictionCoeff     : REAL;     (* Online Observer Estimated Tire-Deck Adhesion Coefficient mu [-] *)
    bEmbarkationSafe            : BOOL;     (* Dynamic Safety Corridor Verified Valid for Ramp Transition *)
    bSystemReady                : BOOL;     (* Overall System Initialized, Interlocked and Operational Ready *)
END_VAR

VAR
    (* --- FINITE STATE MACHINE ARCHITECTURE --- *)
    iState                      : INT := 0; (* Primary Process Execution State Register *)
    iPrevState                  : INT := 0; (* Transition Tracking & Traceability Register *)

    (* --- PHYSICAL, GEOMETRIC & DYNAMIC CONSTANTS --- *)
    rGRAVITY_CONST              : REAL := 9.80665;  (* Earth Standard Gravitational Acceleration [m/s2] *)
    rVEHICLE_WHEELBASE_M        : REAL := 9.2000;   (* Distance Between AGV Front and Rear Wheel Centerlines [m] *)
    rVEHICLE_TRACKWIDTH_M       : REAL := 2.8000;   (* Lateral Wheel Track Width Between Tire Centerlines [m] *)
    rVEHICLE_CG_HEIGHT_M        : REAL := 2.4500;   (* Vehicle Laden Center of Gravity Height Above Deck [m] *)
    rWHEEL_RADIUS_M             : REAL := 0.6500;   (* Nominal Drive Wheel Loaded Rolling Dynamic Radius [m] *)
    rMAX_RAMP_PITCH_DEG         : REAL := 7.5000;   (* Maximum Permissible Dynamic Incline Angle [deg] *)
    rMAX_RAMP_ROLL_DEG          : REAL := 3.5000;   (* Maximum Permissible Transverse Cant Angle [deg] *)
    rMAX_HEAVE_DISP_M           : REAL := 0.8500;   (* Linkspan Flap Dynamic Stroke Displacement Limit [m] *)
    rMAX_FLAP_PIN_LOAD_KN       : REAL := 650.00;   (* Linkspan Hinge Structural Mechanical Plastic Limit [kN] *)
    rTARGET_SLIP_RATIO          : REAL := 0.0800;   (* Peak Tractive Adhesion Target Slip Ratio [-] *)
    rMAX_CRITICAL_SLIP_RATIO    : REAL := 0.1800;   (* Wheel Skid / Spin Runaway Threshold [-] *)
    rMAX_TOTAL_INVERTER_TORQUE  : REAL := 95.000;   (* Combined 4-Corner Maximum Peak Torque Capability [kNm] *)
    rHYDRAULIC_BASE_PRESS_BAR   : REAL := 180.00;   (* Nominal Hydraulic Ramp Counter-balance Pressure [bar] *)

    (* --- 2oo3 TMR SENSOR TOLERANCES & DISCREPANCY TIMERS --- *)
    rPITCH_DISCREPANCY_TOL_DEG  : REAL := 0.8000;   (* Cross-Channel Pitch Inconsistency Threshold [deg] *)
    rHEAVE_DISCREPANCY_TOL_M    : REAL := 0.0600;   (* Cross-Channel Heave Inconsistency Threshold [m] *)
    rLOAD_DISCREPANCY_TOL_KN    : REAL := 45.000;   (* Cross-Channel Loadcell Inconsistency Threshold [kN] *)

    (* 2oo3 Pitch Sensors Status *)
    bDiscrepancyPitch_AB        : BOOL;
    bDiscrepancyPitch_BC        : BOOL;
    bDiscrepancyPitch_CA        : BOOL;
    bPitchSensorA_Fail          : BOOL;
    bPitchSensorB_Fail          : BOOL;
    bPitchSensorC_Fail          : BOOL;
    iHealthyPitchSensors        : INT;

    (* 2oo3 Heave Sensors Status *)
    bDiscrepancyHeave_AB        : BOOL;
    bDiscrepancyHeave_BC        : BOOL;
    bDiscrepancyHeave_CA        : BOOL;
    bHeaveSensorA_Fail          : BOOL;
    bHeaveSensorB_Fail          : BOOL;
    bHeaveSensorC_Fail          : BOOL;
    iHealthyHeaveSensors        : INT;

    (* 2oo3 Finger Flap Loadcells Status *)
    bDiscrepancyLoad_AB         : BOOL;
    bDiscrepancyLoad_BC         : BOOL;
    bDiscrepancyLoad_CA         : BOOL;
    bLoadSensorA_Fail           : BOOL;
    bLoadSensorB_Fail           : BOOL;
    bLoadSensorC_Fail           : BOOL;
    iHealthyLoadSensors         : INT;

    (* --- STATE-SPACE MULTIVARIABLE OBSERVER (KALMAN/LUENBERGER) --- *)
    (* State Vector X: [0]=Pos_Error [m], [1]=Vel_Error [m/s], [2]=YawRate [rad/s],
                       [3]=RampPitch [deg], [4]=HeaveVelocity [m/s], [5]=MeanSlip [-] *)
    rState_X                    : ARRAY[0..5] OF REAL;
    rState_X_Prior              : ARRAY[0..5] OF REAL;

    (* System Matrix A (6x6 Discrete Transition Dynamics at Ts = 0.050s) *)
    rMatrix_A                   : ARRAY[0..5, 0..5] OF REAL := [
        [1.0000, 0.0485, 0.0000, -0.0042,  0.0000,  0.0000],
        [0.0000, 0.9650, 0.0000, -0.0845,  0.0000, -0.0125],
        [0.0000, 0.0000, 0.9200,  0.0000,  0.0000, -0.0450],
        [0.0000, 0.0000, 0.0000,  0.9820,  0.0480,  0.0000],
        [0.0000, 0.0000, 0.0000, -0.0150,  0.9100,  0.0000],
        [0.0000, 0.0025, 0.0000,  0.0000,  0.0000,  0.8850]
    ];

    (* Input Matrix B (6x4: u0=TotalTractiveForce [kN], u1=YawMoment [kNm],
                           u2=HeaveValveFlow [%], u3=CylBalancePress [bar]) *)
    rMatrix_B                   : ARRAY[0..5, 0..3] OF REAL := [
        [ 0.0008,  0.0000,  0.0000,  0.0000],
        [ 0.0245,  0.0000,  0.0000,  0.0000],
        [ 0.0000,  0.0380,  0.0000,  0.0000],
        [ 0.0000,  0.0000, -0.0120, -0.0018],
        [ 0.0000,  0.0000,  0.0450,  0.0085],
        [ 0.0012,  0.0005,  0.0000,  0.0000]
    ];

    (* Measurement Matrix C (4x6: y0=Vel_Error, y1=YawRate, y2=RampPitch, y3=HeaveVelocity) *)
    rMatrix_C                   : ARRAY[0..3, 0..5] OF REAL := [
        [0.0000, 1.0000, 0.0000, 0.0000, 0.0000, 0.0000],
        [0.0000, 0.0000, 1.0000, 0.0000, 0.0000, 0.0000],
        [0.0000, 0.0000, 0.0000, 1.0000, 0.0000, 0.0000],
        [0.0000, 0.0000, 0.0000, 0.0000, 1.0000, 0.0000]
    ];

    (* Observer Gain Matrix L (6x4 Steady-State Optimal Gain) *)
    rMatrix_L                   : ARRAY[0..5, 0..3] OF REAL := [
        [0.2850, 0.0000, 0.0015, 0.0000],
        [0.4500, 0.0000, 0.0180, 0.0000],
        [0.0000, 0.5200, 0.0000, 0.0000],
        [0.0000, 0.0000, 0.4200, 0.0250],
        [0.0000, 0.0000, 0.0350, 0.4800],
        [0.0210, 0.0150, 0.0000, 0.0000]
    ];

    (* --- MODEL PREDICTIVE TRACTION & TORQUE VECTORING (MPC) REGISTERS --- *)
    rControlInput_U             : ARRAY[0..3] OF REAL; (* Unconstrained Computed Demands *)
    rControlInput_Filtered      : ARRAY[0..3] OF REAL; (* Slew Rate Limited Demands *)
    rControlInput_Prior         : ARRAY[0..3] OF REAL; (* Memory Register of Prior Scan *)
    rMaxSlewRateU               : ARRAY[0..3] OF REAL := [45.0, 35.0, 60.0, 25.0]; (* Max Rate per Sec *)

    (* Dynamic Axle and 4-Corner Vertical Normal Loads [kN] *)
    rTotalMass_kg               : REAL;
    rDynamicNormLoad_FL_kN      : REAL;
    rDynamicNormLoad_FR_kN      : REAL;
    rDynamicNormLoad_RL_kN      : REAL;
    rDynamicNormLoad_RR_kN      : REAL;
    rTotalNormalLoad_kN         : REAL;
    rFrontAxleLoad_kN           : REAL;
    rRearAxleLoad_kN            : REAL;

    (* Corner Acceleration Vectors *)
    rLongitudinalAccel_mps2     : REAL;
    rLateralAccel_mps2          : REAL;
    rVerticalHeaveAccel_mps2    : REAL;
    rRadPitchAngle              : REAL;
    rRadRollAngle               : REAL;

    (* Wheel Slip Ratios [-] *)
    rSlip_FL                    : REAL;
    rSlip_FR                    : REAL;
    rSlip_RL                    : REAL;
    rSlip_RR                    : REAL;
    rMeanSlipRatio              : REAL;

    (* Tire Adhesion Capacities & Force Demands [kN] *)
    rFrictionEstimate           : REAL := 0.6500; (* Nominal clean dry steel ramp baseline *)
    rAdhesionLimit_FL_kN        : REAL;
    rAdhesionLimit_FR_kN        : REAL;
    rAdhesionLimit_RL_kN        : REAL;
    rAdhesionLimit_RR_kN        : REAL;
    rForceDemand_FL_kN          : REAL;
    rForceDemand_FR_kN          : REAL;
    rForceDemand_RL_kN          : REAL;
    rForceDemand_RR_kN          : REAL;
    rTargetYawMoment_kNm        : REAL;
    rTotalTractionForce_kN      : REAL;

    (* Torque Vectoring Internal Intermediate Variables *)
    rRawTorque_FL_kNm           : REAL;
    rRawTorque_FR_kNm           : REAL;
    rRawTorque_RL_kNm           : REAL;
    rRawTorque_RR_kNm           : REAL;
    rTorquePrev_FL_kNm          : REAL;
    rTorquePrev_FR_kNm          : REAL;
    rTorquePrev_RL_kNm          : REAL;
    rTorquePrev_RR_kNm          : REAL;
    rTorqueRateLimit_kNmPerSec  : REAL := 25.0;

    (* Dynamic Heave Velocity & Compensation *)
    rPriorHeaveDisp_M           : REAL;
    rDerivedHeaveVelocity_mps   : REAL;
    rCalculatedCylFlow_Pct      : REAL;
    rCalculatedCylPress_bar     : REAL;

    (* Internal Scratchpad & Matrix Arithmetic Registers *)
    iIdxRow                     : INT;
    iIdxCol                     : INT;
    rInnovationResidual         : ARRAY[0..3] OF REAL;
    rMatrixAccum                : REAL;
    rMaxCycleDelta              : REAL;
    rVelocityDeviation          : REAL;
    rMeasuredYawRate_radps      : REAL;

    (* Timers and Safety Enunciators *)
    tEmbarkDwellTimer           : TON;
    tTractionRecoveryTimer      : TON;
    tWaveSlamTripTimer          : TON;
    bCriticalTractionLoss       : BOOL;
    bWaveSlamDetected           : BOOL;
END_VAR

(*
 * ====================================================================================================
 * SECTION 0: SAFETY HARDWIRED INTERLOCK EVALUATION & SCAN INTERVAL NORMALIZATION
 * ====================================================================================================
 *)
(* Evaluate Safety Interlock Cat-4 / SIL-3 Emergency Stop Loop (Active-Low) *)
IF NOT bEmergencyStop THEN
    rTorqueDemand_FL_kNm         := 0.0;
    rTorqueDemand_FR_kNm         := 0.0;
    rTorqueDemand_RL_kNm         := 0.0;
    rTorqueDemand_RR_kNm         := 0.0;
    rHydraulicCylFlowDemand_Pct  := 0.0;
    rHydraulicCylPressDemand_bar := rHYDRAULIC_BASE_PRESS_BAR;
    bEmbarkationSafe             := FALSE;
    bSystemReady                 := FALSE;
    wSystemStatusWord            := 16#F000; (* Emergency Safety Shutdown State *)
    wAlarmWord                   := wAlarmWord OR 16#2000; (* Bit 13: Emergency Stop Loop Tripped *)
    iState                       := 99;
    RETURN;
END_IF;

(* Normalize Execution Scan Interval if not provided by hardware task scheduler *)
IF rCycleTimeSec <= 0.0005 OR rCycleTimeSec > 1.0000 THEN
    rCycleTimeSec := 0.0500; (* Default 50ms Deterministic AGV Control Task Interval *)
END_IF;

(*
 * ====================================================================================================
 * SECTION 1: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & SENSOR VALIDATION
 * ====================================================================================================
 *)
(* --- 1.1: 2oo3 PITCH ANGLE SENSOR EVALUATION --- *)
bPitchSensorA_Fail := (rRampPitch_Deg_A < -15.0) OR (rRampPitch_Deg_A > 15.0);
bPitchSensorB_Fail := (rRampPitch_Deg_B < -15.0) OR (rRampPitch_Deg_B > 15.0);
bPitchSensorC_Fail := (rRampPitch_Deg_C < -15.0) OR (rRampPitch_Deg_C > 15.0);

bDiscrepancyPitch_AB := ABS(rRampPitch_Deg_A - rRampPitch_Deg_B) > rPITCH_DISCREPANCY_TOL_DEG;
bDiscrepancyPitch_BC := ABS(rRampPitch_Deg_B - rRampPitch_Deg_C) > rPITCH_DISCREPANCY_TOL_DEG;
bDiscrepancyPitch_CA := ABS(rRampPitch_Deg_C - rRampPitch_Deg_A) > rPITCH_DISCREPANCY_TOL_DEG;

IF bDiscrepancyPitch_AB AND bDiscrepancyPitch_CA THEN bPitchSensorA_Fail := TRUE; END_IF;
IF bDiscrepancyPitch_AB AND bDiscrepancyPitch_BC THEN bPitchSensorB_Fail := TRUE; END_IF;
IF bDiscrepancyPitch_BC AND bDiscrepancyPitch_CA THEN bPitchSensorC_Fail := TRUE; END_IF;

iHealthyPitchSensors := 3;
IF bPitchSensorA_Fail THEN iHealthyPitchSensors := iHealthyPitchSensors - 1; END_IF;
IF bPitchSensorB_Fail THEN iHealthyPitchSensors := iHealthyPitchSensors - 1; END_IF;
IF bPitchSensorC_Fail THEN iHealthyPitchSensors := iHealthyPitchSensors - 1; END_IF;

IF iHealthyPitchSensors = 3 THEN
    (* Full 2oo3 Median Selection *)
    IF (rRampPitch_Deg_A >= rRampPitch_Deg_B AND rRampPitch_Deg_A <= rRampPitch_Deg_C) OR
       (rRampPitch_Deg_A <= rRampPitch_Deg_B AND rRampPitch_Deg_A >= rRampPitch_Deg_C) THEN
        rVotedRampPitch_Deg := rRampPitch_Deg_A;
    ELSIF (rRampPitch_Deg_B >= rRampPitch_Deg_A AND rRampPitch_Deg_B <= rRampPitch_Deg_C) OR
          (rRampPitch_Deg_B <= rRampPitch_Deg_A AND rRampPitch_Deg_B >= rRampPitch_Deg_C) THEN
        rVotedRampPitch_Deg := rRampPitch_Deg_B;
    ELSE
        rVotedRampPitch_Deg := rRampPitch_Deg_C;
    END_IF;
ELSIF iHealthyPitchSensors = 2 THEN
    (* Degraded 1oo2 Dual Averaging *)
    IF NOT bPitchSensorA_Fail AND NOT bPitchSensorB_Fail THEN
        rVotedRampPitch_Deg := 0.5 * (rRampPitch_Deg_A + rRampPitch_Deg_B);
    ELSIF NOT bPitchSensorB_Fail AND NOT bPitchSensorC_Fail THEN
        rVotedRampPitch_Deg := 0.5 * (rRampPitch_Deg_B + rRampPitch_Deg_C);
    ELSE
        rVotedRampPitch_Deg := 0.5 * (rRampPitch_Deg_A + rRampPitch_Deg_C);
    END_IF;
    wAlarmWord := wAlarmWord OR 16#0400; (* Bit 10: Pitch Sensor Degraded 1oo2 *)
ELSIF iHealthyPitchSensors = 1 THEN
    (* Single Surviving Sensor Mode *)
    IF NOT bPitchSensorA_Fail THEN
        rVotedRampPitch_Deg := rRampPitch_Deg_A;
    ELSIF NOT bPitchSensorB_Fail THEN
        rVotedRampPitch_Deg := rRampPitch_Deg_B;
    ELSE
        rVotedRampPitch_Deg := rRampPitch_Deg_C;
    END_IF;
    wAlarmWord := wAlarmWord OR 16#0400;
ELSE
    rVotedRampPitch_Deg := rMAX_RAMP_PITCH_DEG;
    iState := 90; (* Abort: Total Pitch Blackout *)
END_IF;

(* --- 1.2: 2oo3 VESSEL HEAVE DISPLACEMENT TELEMETRY EVALUATION --- *)
bHeaveSensorA_Fail := (rFerryHeaveDisp_M_A < -2.0) OR (rFerryHeaveDisp_M_A > 2.0);
bHeaveSensorB_Fail := (rFerryHeaveDisp_M_B < -2.0) OR (rFerryHeaveDisp_M_B > 2.0);
bHeaveSensorC_Fail := (rFerryHeaveDisp_M_C < -2.0) OR (rFerryHeaveDisp_M_C > 2.0);

bDiscrepancyHeave_AB := ABS(rFerryHeaveDisp_M_A - rFerryHeaveDisp_M_B) > rHEAVE_DISCREPANCY_TOL_M;
bDiscrepancyHeave_BC := ABS(rFerryHeaveDisp_M_B - rFerryHeaveDisp_M_C) > rHEAVE_DISCREPANCY_TOL_M;
bDiscrepancyHeave_CA := ABS(rFerryHeaveDisp_M_C - rFerryHeaveDisp_M_A) > rHEAVE_DISCREPANCY_TOL_M;

IF bDiscrepancyHeave_AB AND bDiscrepancyHeave_CA THEN bHeaveSensorA_Fail := TRUE; END_IF;
IF bDiscrepancyHeave_AB AND bDiscrepancyHeave_BC THEN bHeaveSensorB_Fail := TRUE; END_IF;
IF bDiscrepancyHeave_BC AND bDiscrepancyHeave_CA THEN bHeaveSensorC_Fail := TRUE; END_IF;

iHealthyHeaveSensors := 3;
IF bHeaveSensorA_Fail THEN iHealthyHeaveSensors := iHealthyHeaveSensors - 1; END_IF;
IF bHeaveSensorB_Fail THEN iHealthyHeaveSensors := iHealthyHeaveSensors - 1; END_IF;
IF bHeaveSensorC_Fail THEN iHealthyHeaveSensors := iHealthyHeaveSensors - 1; END_IF;

IF iHealthyHeaveSensors = 3 THEN
    IF (rFerryHeaveDisp_M_A >= rFerryHeaveDisp_M_B AND rFerryHeaveDisp_M_A <= rFerryHeaveDisp_M_C) OR
       (rFerryHeaveDisp_M_A <= rFerryHeaveDisp_M_B AND rFerryHeaveDisp_M_A >= rFerryHeaveDisp_M_C) THEN
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_A;
    ELSIF (rFerryHeaveDisp_M_B >= rFerryHeaveDisp_M_A AND rFerryHeaveDisp_M_B <= rFerryHeaveDisp_M_C) OR
          (rFerryHeaveDisp_M_B <= rFerryHeaveDisp_M_A AND rFerryHeaveDisp_M_B >= rFerryHeaveDisp_M_C) THEN
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_B;
    ELSE
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_C;
    END_IF;
ELSIF iHealthyHeaveSensors = 2 THEN
    IF NOT bHeaveSensorA_Fail AND NOT bHeaveSensorB_Fail THEN
        rVotedHeaveDisp_M := 0.5 * (rFerryHeaveDisp_M_A + rFerryHeaveDisp_M_B);
    ELSIF NOT bHeaveSensorB_Fail AND NOT bHeaveSensorC_Fail THEN
        rVotedHeaveDisp_M := 0.5 * (rFerryHeaveDisp_M_B + rFerryHeaveDisp_M_C);
    ELSE
        rVotedHeaveDisp_M := 0.5 * (rFerryHeaveDisp_M_A + rFerryHeaveDisp_M_C);
    END_IF;
    wAlarmWord := wAlarmWord OR 16#0800; (* Bit 11: Heave Sensor Degraded 1oo2 *)
ELSIF iHealthyHeaveSensors = 1 THEN
    IF NOT bHeaveSensorA_Fail THEN
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_A;
    ELSIF NOT bHeaveSensorB_Fail THEN
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_B;
    ELSE
        rVotedHeaveDisp_M := rFerryHeaveDisp_M_C;
    END_IF;
    wAlarmWord := wAlarmWord OR 16#0800;
ELSE
    rVotedHeaveDisp_M := rMAX_HEAVE_DISP_M;
    iState := 90;
END_IF;

(* --- 1.3: 2oo3 FINGER FLAP BEARING REACTION LOADCELLS EVALUATION --- *)
bLoadSensorA_Fail := (rFlapBearingLoad_kN_A < -50.0) OR (rFlapBearingLoad_kN_A > 1000.0);
bLoadSensorB_Fail := (rFlapBearingLoad_kN_B < -50.0) OR (rFlapBearingLoad_kN_B > 1000.0);
bLoadSensorC_Fail := (rFlapBearingLoad_kN_C < -50.0) OR (rFlapBearingLoad_kN_C > 1000.0);

bDiscrepancyLoad_AB := ABS(rFlapBearingLoad_kN_A - rFlapBearingLoad_kN_B) > rLOAD_DISCREPANCY_TOL_KN;
bDiscrepancyLoad_BC := ABS(rFlapBearingLoad_kN_B - rFlapBearingLoad_kN_C) > rLOAD_DISCREPANCY_TOL_KN;
bDiscrepancyLoad_CA := ABS(rFlapBearingLoad_kN_C - rFlapBearingLoad_kN_A) > rLOAD_DISCREPANCY_TOL_KN;

IF bDiscrepancyLoad_AB AND bDiscrepancyLoad_CA THEN bLoadSensorA_Fail := TRUE; END_IF;
IF bDiscrepancyLoad_AB AND bDiscrepancyLoad_BC THEN bLoadSensorB_Fail := TRUE; END_IF;
IF bDiscrepancyLoad_BC AND bDiscrepancyLoad_CA THEN bLoadSensorC_Fail := TRUE; END_IF;

iHealthyLoadSensors := 3;
IF bLoadSensorA_Fail THEN iHealthyLoadSensors := iHealthyLoadSensors - 1; END_IF;
IF bLoadSensorB_Fail THEN iHealthyLoadSensors := iHealthyLoadSensors - 1; END_IF;
IF bLoadSensorC_Fail THEN iHealthyLoadSensors := iHealthyLoadSensors - 1; END_IF;

IF iHealthyLoadSensors = 3 THEN
    IF (rFlapBearingLoad_kN_A >= rFlapBearingLoad_kN_B AND rFlapBearingLoad_kN_A <= rFlapBearingLoad_kN_C) OR
       (rFlapBearingLoad_kN_A <= rFlapBearingLoad_kN_B AND rFlapBearingLoad_kN_A >= rFlapBearingLoad_kN_C) THEN
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_A;
    ELSIF (rFlapBearingLoad_kN_B >= rFlapBearingLoad_kN_A AND rFlapBearingLoad_kN_B <= rFlapBearingLoad_kN_C) OR
          (rFlapBearingLoad_kN_B <= rFlapBearingLoad_kN_A AND rFlapBearingLoad_kN_B >= rFlapBearingLoad_kN_C) THEN
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_B;
    ELSE
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_C;
    END_IF;
ELSIF iHealthyLoadSensors = 2 THEN
    IF NOT bLoadSensorA_Fail AND NOT bLoadSensorB_Fail THEN
        rVotedFlapLoad_kN := 0.5 * (rFlapBearingLoad_kN_A + rFlapBearingLoad_kN_B);
    ELSIF NOT bLoadSensorB_Fail AND NOT bLoadSensorC_Fail THEN
        rVotedFlapLoad_kN := 0.5 * (rFlapBearingLoad_kN_B + rFlapBearingLoad_kN_C);
    ELSE
        rVotedFlapLoad_kN := 0.5 * (rFlapBearingLoad_kN_A + rFlapBearingLoad_kN_C);
    END_IF;
    wAlarmWord := wAlarmWord OR 16#1000; (* Bit 12: Loadcell Degraded 1oo2 *)
ELSIF iHealthyLoadSensors = 1 THEN
    IF NOT bLoadSensorA_Fail THEN
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_A;
    ELSIF NOT bLoadSensorB_Fail THEN
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_B;
    ELSE
        rVotedFlapLoad_kN := rFlapBearingLoad_kN_C;
    END_IF;
    wAlarmWord := wAlarmWord OR 16#1000;
ELSE
    rVotedFlapLoad_kN := rMAX_FLAP_PIN_LOAD_KN;
    iState := 90;
END_IF;

(*
 * ====================================================================================================
 * SECTION 2: 4-CORNER DYNAMIC NORMAL LOAD DISTRIBUTION CALCULATIONS
 * ====================================================================================================
 *)
(* Convert Gross Vehicle Weight to Total Mass in Kilograms [ton -> kg] *)
rTotalMass_kg := LIMIT(20.0, rAGV_GrossVehicleWeight_Ton, 140.0) * 1000.0;

(* Calculate Trigonometric Angles in Radians *)
rRadPitchAngle := rVotedRampPitch_Deg * 0.0174533;
rRadRollAngle  := rRampRoll_Deg * 0.0174533;

(* Derive Dynamic Accelerations *)
rLongitudinalAccel_mps2 := (rAGV_LongitudinalVelocity_mps - rState_X_Prior[1]) / rCycleTimeSec;
rLateralAccel_mps2      := (rAGV_LongitudinalVelocity_mps * rAGV_LongitudinalVelocity_mps / (rVEHICLE_WHEELBASE_M / TAN(MAX(ABS(rAGV_SteeringAngle_Deg * 0.0174533), 0.001))));
IF rAGV_SteeringAngle_Deg < 0.0 THEN
    rLateralAccel_mps2 := -rLateralAccel_mps2;
END_IF;

rDerivedHeaveVelocity_mps := (rVotedHeaveDisp_M - rPriorHeaveDisp_M) / rCycleTimeSec;
rVerticalHeaveAccel_mps2  := (rDerivedHeaveVelocity_mps - rState_X_Prior[4]) / rCycleTimeSec;
rPriorHeaveDisp_M         := rVotedHeaveDisp_M;

(* Total Normal Reaction Force Acting Through Vehicle Center of Gravity [kN] *)
rTotalNormalLoad_kN := (rTotalMass_kg * (rGRAVITY_CONST * COS(rRadPitchAngle) * COS(rRadRollAngle) - rVerticalHeaveAccel_mps2)) / 1000.0;
rTotalNormalLoad_kN := MAX(10.0, rTotalNormalLoad_kN);

(* Longitudinal Load Transfer Due to Ramp Incline and Dynamic Tractive Acceleration *)
rFrontAxleLoad_kN := (rTotalNormalLoad_kN * 0.50) -
                     ((rTotalMass_kg * (rLongitudinalAccel_mps2 + rGRAVITY_CONST * SIN(rRadPitchAngle)) * rVEHICLE_CG_HEIGHT_M / rVEHICLE_WHEELBASE_M) / 1000.0);
rRearAxleLoad_kN  := (rTotalNormalLoad_kN * 0.50) +
                     ((rTotalMass_kg * (rLongitudinalAccel_mps2 + rGRAVITY_CONST * SIN(rRadPitchAngle)) * rVEHICLE_CG_HEIGHT_M / rVEHICLE_WHEELBASE_M) / 1000.0);

rFrontAxleLoad_kN := LIMIT(5.0, rFrontAxleLoad_kN, rTotalNormalLoad_kN - 5.0);
rRearAxleLoad_kN  := rTotalNormalLoad_kN - rFrontAxleLoad_kN;

(* Lateral Load Transfer Across Wheel Track Due to Ramp Roll and Centrifugal Steer Lateral Accel *)
rDynamicNormLoad_FL_kN := (rFrontAxleLoad_kN * 0.50) -
                          ((rTotalMass_kg * (rLateralAccel_mps2 + rGRAVITY_CONST * SIN(rRadRollAngle)) * rVEHICLE_CG_HEIGHT_M * (0.50 / rVEHICLE_TRACKWIDTH_M)) / 1000.0);
rDynamicNormLoad_FR_kN := rFrontAxleLoad_kN - rDynamicNormLoad_FL_kN;

rDynamicNormLoad_RL_kN := (rRearAxleLoad_kN * 0.50) -
                          ((rTotalMass_kg * (rLateralAccel_mps2 + rGRAVITY_CONST * SIN(rRadRollAngle)) * rVEHICLE_CG_HEIGHT_M * (0.50 / rVEHICLE_TRACKWIDTH_M)) / 1000.0);
rDynamicNormLoad_RR_kN := rRearAxleLoad_kN - rDynamicNormLoad_RL_kN;

(* Enforce Positive Normal Tire Contact Constraint (Ground Contact Guarantee) *)
rDynamicNormLoad_FL_kN := MAX(2.0, rDynamicNormLoad_FL_kN);
rDynamicNormLoad_FR_kN := MAX(2.0, rDynamicNormLoad_FR_kN);
rDynamicNormLoad_RL_kN := MAX(2.0, rDynamicNormLoad_RL_kN);
rDynamicNormLoad_RR_kN := MAX(2.0, rDynamicNormLoad_RR_kN);

(*
 * ====================================================================================================
 * SECTION 3: TIRE SLIP RATIO EVALUATION & FRICTION ADHESION ESTIMATION
 * ====================================================================================================
 *)
(* Evaluate Individual Wheel Longitudinal Slip: lambda = (omega * R - v) / MAX(omega * R, v) *)
IF rAGV_LongitudinalVelocity_mps > 0.100 THEN
    rSlip_FL := (rWheelSpeed_FL_mps - rAGV_LongitudinalVelocity_mps) / MAX(rWheelSpeed_FL_mps, rAGV_LongitudinalVelocity_mps);
    rSlip_FR := (rWheelSpeed_FR_mps - rAGV_LongitudinalVelocity_mps) / MAX(rWheelSpeed_FR_mps, rAGV_LongitudinalVelocity_mps);
    rSlip_RL := (rWheelSpeed_RL_mps - rAGV_LongitudinalVelocity_mps) / MAX(rWheelSpeed_RL_mps, rAGV_LongitudinalVelocity_mps);
    rSlip_RR := (rWheelSpeed_RR_mps - rAGV_LongitudinalVelocity_mps) / MAX(rWheelSpeed_RR_mps, rAGV_LongitudinalVelocity_mps);
ELSE
    rSlip_FL := 0.0;
    rSlip_FR := 0.0;
    rSlip_RL := 0.0;
    rSlip_RR := 0.0;
END_IF;

rMeanSlipRatio := 0.25 * (ABS(rSlip_FL) + ABS(rSlip_FR) + ABS(rSlip_RL) + ABS(rSlip_RR));

(* Online Recursive Estimation of Deck Surface Adhesion Friction (mu) *)
IF rMeanSlipRatio > 0.030 AND rMeanSlipRatio < 0.120 AND ABS(rLongitudinalAccel_mps2) > 0.10 THEN
    (* Peak Adhesion Identification Region *)
    rFrictionEstimate := (0.98 * rFrictionEstimate) + (0.02 * (ABS(rLongitudinalAccel_mps2 + rGRAVITY_CONST * SIN(rRadPitchAngle)) / rGRAVITY_CONST));
END_IF;
rEstimatedFrictionCoeff := LIMIT(0.180, rFrictionEstimate, 0.850);

(* Maximum Permissible Adhesion Forces Before Dynamic Wheel Spin Breakaway [kN] *)
rAdhesionLimit_FL_kN := rDynamicNormLoad_FL_kN * rEstimatedFrictionCoeff;
rAdhesionLimit_FR_kN := rDynamicNormLoad_FR_kN * rEstimatedFrictionCoeff;
rAdhesionLimit_RL_kN := rDynamicNormLoad_RL_kN * rEstimatedFrictionCoeff;
rAdhesionLimit_RR_kN := rDynamicNormLoad_RR_kN * rEstimatedFrictionCoeff;

(*
 * ====================================================================================================
 * SECTION 4: STATE-SPACE OBSERVER (KALMAN/LUENBERGER) MEASUREMENT UPDATE
 * ====================================================================================================
 *)
rVelocityDeviation     := rTargetVelocity_mps - rAGV_LongitudinalVelocity_mps;
rMeasuredYawRate_radps := (rAGV_LongitudinalVelocity_mps / rVEHICLE_WHEELBASE_M) * TAN(rAGV_SteeringAngle_Deg * 0.0174533);

(* Compute Measurement Innovation Residual: y_meas - C * x_prior *)
rInnovationResidual[0] := rVelocityDeviation          - (rMatrix_C[0, 1] * rState_X_Prior[1]);
rInnovationResidual[1] := rMeasuredYawRate_radps      - (rMatrix_C[1, 2] * rState_X_Prior[2]);
rInnovationResidual[2] := rVotedRampPitch_Deg         - (rMatrix_C[2, 3] * rState_X_Prior[3]);
rInnovationResidual[3] := rDerivedHeaveVelocity_mps   - (rMatrix_C[3, 4] * rState_X_Prior[4]);

(* State Correction Step: X_hat(k) = X_prior(k) + L * Innovation *)
FOR iIdxRow := 0 TO 5 DO
    rMatrixAccum := 0.0;
    FOR iIdxCol := 0 TO 3 DO
        rMatrixAccum := rMatrixAccum + (rMatrix_L[iIdxRow, iIdxCol] * rInnovationResidual[iIdxCol]);
    END_FOR;
    rState_X[iIdxRow] := rState_X_Prior[iIdxRow] + rMatrixAccum;
END_FOR;

(*
 * ====================================================================================================
 * SECTION 5: ISA-18.2 ALARM TAXONOMY & SAFETY BOUND EVALUATION
 * ====================================================================================================
 *)
(* Reset Transitory Alarm Bits Prior to Evaluation *)
wAlarmWord := wAlarmWord AND 16#FF00;

(* Pitch Angle Warnings & Trips *)
IF ABS(rVotedRampPitch_Deg) > 5.50 THEN
    wAlarmWord := wAlarmWord OR 16#0001; (* Bit 0: Pitch High Warning *)
END_IF;
IF ABS(rVotedRampPitch_Deg) >= rMAX_RAMP_PITCH_DEG THEN
    wAlarmWord := wAlarmWord OR 16#0002; (* Bit 1: Pitch High-High Critical Trip *)
END_IF;

(* Roll Angle Warnings & Trips *)
IF ABS(rRampRoll_Deg) > 2.50 THEN
    wAlarmWord := wAlarmWord OR 16#0004; (* Bit 2: Roll High Warning *)
END_IF;
IF ABS(rRampRoll_Deg) >= rMAX_RAMP_ROLL_DEG THEN
    wAlarmWord := wAlarmWord OR 16#0008; (* Bit 3: Roll High-High Critical Trip *)
END_IF;

(* Relative Heave Warnings & Trips *)
IF ABS(rVotedHeaveDisp_M) > 0.650 THEN
    wAlarmWord := wAlarmWord OR 16#0010; (* Bit 4: Heave Displacement High Warning *)
END_IF;
IF ABS(rVotedHeaveDisp_M) >= rMAX_HEAVE_DISP_M THEN
    wAlarmWord := wAlarmWord OR 16#0020; (* Bit 5: Heave Displacement Critical Trip *)
END_IF;

(* Flap Reaction Load Warnings & Structural Trips *)
IF rVotedFlapLoad_kN > 550.0 THEN
    wAlarmWord := wAlarmWord OR 16#0040; (* Bit 6: Flap Pin Load High Warning *)
END_IF;
IF rVotedFlapLoad_kN >= rMAX_FLAP_PIN_LOAD_KN THEN
    wAlarmWord := wAlarmWord OR 16#0080; (* Bit 7: Flap Pin Overload Structural Trip *)
END_IF;

(* Dynamic Wheel Slip Adhesion Breakdown *)
IF rMeanSlipRatio > rMAX_CRITICAL_SLIP_RATIO THEN
    bCriticalTractionLoss := TRUE;
    wAlarmWord := wAlarmWord OR 16#0100; (* Bit 8: Wheel Slip Critical Loss of Traction *)
ELSE
    bCriticalTractionLoss := FALSE;
END_IF;

(* Low Friction Adhesion Deck Warning *)
IF rEstimatedFrictionCoeff < 0.250 THEN
    wAlarmWord := wAlarmWord OR 16#0200; (* Bit 9: Low Surface Adhesion Risk *)
END_IF;

(* Wave Slam / Severe Dynamic Acceleration Transient *)
tWaveSlamTripTimer(IN := (ABS(rVerticalHeaveAccel_mps2) > 2.80 OR ABS(rDerivedHeaveVelocity_mps) > 1.20), PT := T#0.3S);
IF tWaveSlamTripTimer.Q THEN
    bWaveSlamDetected := TRUE;
    wAlarmWord := wAlarmWord OR 16#4000; (* Bit 14: Dynamic Wave Slam Detected *)
ELSE
    bWaveSlamDetected := FALSE;
END_IF;

(* Critical Embarkation Safety Envelope Evaluation *)
bEmbarkationSafe := (ABS(rVotedRampPitch_Deg) < rMAX_RAMP_PITCH_DEG) AND
                    (ABS(rRampRoll_Deg) < rMAX_RAMP_ROLL_DEG) AND
                    (ABS(rVotedHeaveDisp_M) < rMAX_HEAVE_DISP_M) AND
                    (rVotedFlapLoad_kN < rMAX_FLAP_PIN_LOAD_KN) AND
                    (iHealthyPitchSensors >= 2) AND
                    (iHealthyHeaveSensors >= 2) AND
                    NOT bWaveSlamDetected;

(*
 * ====================================================================================================
 * SECTION 6: MULTI-STAGE SEQUENTIAL EMBARKATION FINITE STATE MACHINE
 * ====================================================================================================
 *)
iPrevState := iState;

CASE iState OF
    0: (* STATE 0: UNINITIALIZED / SENSOR PRE-CHECK & INTERLOCK VERIFICATION *)
        bSystemReady                := FALSE;
        rControlInput_U[0]          := 0.0;
        rControlInput_U[1]          := 0.0;
        rControlInput_U[2]          := 0.0;
        rControlInput_U[3]          := rHYDRAULIC_BASE_PRESS_BAR;

        IF bMasterEnable AND bEmbarkationSafe AND (iHealthyPitchSensors = 3) AND (iHealthyHeaveSensors = 3) THEN
            bSystemReady := TRUE;
            iState := 10; (* Transition to Approach & Wave Synchronization *)
        END_IF;

    10: (* STATE 10: QUAYSIDE EMBARKATION APPROACH & LINKSPAN PRE-SYNCHRONIZATION *)
        bSystemReady := TRUE;
        (* Regulate AGV Approach Speed to 1.5 m/s *)
        rControlInput_U[0] := (1.50 - rAGV_LongitudinalVelocity_mps) * 12.0;
        rControlInput_U[1] := 0.0;
        (* Ramp Active Compensation Follows Ferry Heave to Minimize Flap Mismatch *)
        rControlInput_U[2] := LIMIT(-50.0, -rState_X[4] * 40.0, 50.0);
        rControlInput_U[3] := rHYDRAULIC_BASE_PRESS_BAR;

        (* Check Transition Trigger: Proximity to Ramp Shore Abutment Ingress *)
        IF bEmbarkationSafe AND (rAGV_LongitudinalVelocity_mps > 0.50) AND (rTargetVelocity_mps > 0.0) THEN
            iState := 20; (* Advance to Ramp Ingress *)
        END_IF;

    20: (* STATE 20: RAMP INGRESS & SHORE ABUTMENT TRANSITION *)
        bSystemReady := TRUE;
        (* Controlled Ingress: Ramp Pitch Load Compensation *)
        rControlInput_U[0] := ((rTargetVelocity_mps - rAGV_LongitudinalVelocity_mps) * 18.0) +
                              (rTotalNormalLoad_kN * SIN(rRadPitchAngle));
        rControlInput_U[1] := -rState_X[2] * 25.0; (* Dampen Any Ingress Yaw Oscillation *)
        rControlInput_U[2] := LIMIT(-75.0, -rState_X[4] * 55.0, 75.0);
        rControlInput_U[3] := rHYDRAULIC_BASE_PRESS_BAR + (rVotedFlapLoad_kN * 0.08);

        (* Check Transition to Midspan Cruise *)
        IF rVotedFlapLoad_kN > 120.0 THEN
            iState := 30; (* Advance to Midspan Motion Compensated Transit *)
        ELSIF NOT bEmbarkationSafe THEN
            iState := 90; (* Abort to Emergency Braking *)
        END_IF;

    30: (* STATE 30: MIDSPAN MOTION-COMPENSATED TRANSIT & ACTIVE VECTORING *)
        bSystemReady := TRUE;
        (* Full Multivariable Model Predictive Control Law *)
        rControlInput_U[0] := ((rTargetVelocity_mps - rAGV_LongitudinalVelocity_mps) * 22.0) +
                              (rTotalNormalLoad_kN * SIN(rRadPitchAngle)) +
                              (rState_X[0] * 4.5);
        (* Direct Yaw Moment Vectoring for Cross-Roll and Asymmetric Friction Compensation *)
        rControlInput_U[1] := (-rState_X[2] * 32.0) + (rRampRoll_Deg * 4.5);
        (* Dynamic Heave Active Valve Demand *)
        rControlInput_U[2] := LIMIT(-100.0, (-rState_X[4] * 70.0) - (rVotedHeaveDisp_M * 35.0), 100.0);
        (* Counter-balance Hydraulic Support Demand Proportional to Current Flap Weight *)
        rControlInput_U[3] := rHYDRAULIC_BASE_PRESS_BAR + (rVotedFlapLoad_kN * 0.12);

        (* Evaluate Loss of Traction *)
        IF bCriticalTractionLoss THEN
            iState := 80; (* Engage Traction Loss Recovery *)
        (* Evaluate Impending Threshold Embarkation *)
        ELSIF rVotedFlapLoad_kN > 380.0 THEN
            iState := 40; (* Transition Over Ferry Threshold Flap *)
        ELSIF NOT bEmbarkationSafe THEN
            iState := 90;
        END_IF;

    40: (* STATE 40: VESSEL FINGER FLAP EMBARKATION & DECK TOUCHDOWN *)
        bSystemReady := TRUE;
        (* Speed Reduction during Critical Transition Plate Crossing *)
        rControlInput_U[0] := ((1.00 - rAGV_LongitudinalVelocity_mps) * 25.0) +
                              (rTotalNormalLoad_kN * SIN(rRadPitchAngle));
        rControlInput_U[1] := -rState_X[2] * 40.0;
        (* High-Damping Cylinder Flow Demand to Prevent Flap Wave Slam *)
        rControlInput_U[2] := LIMIT(-40.0, -rState_X[4] * 30.0, 40.0);
        rControlInput_U[3] := rHYDRAULIC_BASE_PRESS_BAR + 25.0;

        (* Dwell Timer to Ensure Full AGV Rear Axle Deck Clearance *)
        tEmbarkDwellTimer(IN := (rAGV_LongitudinalVelocity_mps > 0.20 AND rVotedFlapLoad_kN < 150.0), PT := T#4.0S);
        IF tEmbarkDwellTimer.Q THEN
            tEmbarkDwellTimer(IN := FALSE);
            iState := 50; (* Embarkation Successfully Completed *)
        ELSIF bCriticalTractionLoss THEN
            iState := 80;
        ELSIF NOT bEmbarkationSafe THEN
            iState := 90;
        END_IF;

    50: (* STATE 50: ONBOARD SHIP EMBARKATION COMPLETED & SECURED *)
        bSystemReady                := TRUE;
        rControlInput_U[0]          := 0.0; (* Decelerate to Complete Rest *)
        rControlInput_U[1]          := 0.0;
        rControlInput_U[2]          := 0.0;
        rControlInput_U[3]          := rHYDRAULIC_BASE_PRESS_BAR;

        IF rAGV_LongitudinalVelocity_mps < 0.05 THEN
            wSystemStatusWord := 16#0050; (* Secured Onboard Ferry Status *)
        END_IF;

    80: (* STATE 80: TRACTION LOSS / LOW ADHESION RECOVERY PROTOCOL *)
        bSystemReady := TRUE;
        wAlarmWord   := wAlarmWord OR 16#0100;
        (* Immediate Torque Cut to Allow Tire Adhesion Regain *)
        rControlInput_U[0] := MAX(0.0, rControlInput_Prior[0] * 0.50);
        rControlInput_U[1] := 0.0; (* Zero Out Yaw Moment During Spin Recovery *)
        rControlInput_U[2] := LIMIT(-50.0, -rState_X[4] * 45.0, 50.0);
        rControlInput_U[3] := rHYDRAULIC_BASE_PRESS_BAR;

        tTractionRecoveryTimer(IN := (rMeanSlipRatio < rTARGET_SLIP_RATIO), PT := T#1.5S);
        IF tTractionRecoveryTimer.Q THEN
            tTractionRecoveryTimer(IN := FALSE);
            iState := 30; (* Return to Midspan Cruise *)
        END_IF;

    90: (* STATE 90: EMERGENCY EMBARKATION ABORT & HARDWARE BRAKING *)
        bSystemReady                := FALSE;
        bEmbarkationSafe            := FALSE;
        rControlInput_U[0]          := -45.0; (* Dynamic Regenerative / Friction Brake Demand *)
        rControlInput_U[1]          := 0.0;
        rControlInput_U[2]          := 0.0;
        rControlInput_U[3]          := rHYDRAULIC_BASE_PRESS_BAR + 40.0; (* Hydraulic Stiffening *)
        wAlarmWord                  := wAlarmWord OR 16#8000; (* Bit 15: Emergency Abort Active *)

        IF rAGV_LongitudinalVelocity_mps <= 0.02 THEN
            rControlInput_U[0] := 0.0;
        END_IF;

    99: (* STATE 99: SAFETY ESD LOCKOUT STATE *)
        bSystemReady                := FALSE;
        bEmbarkationSafe            := FALSE;
        rControlInput_U[0]          := 0.0;
        rControlInput_U[1]          := 0.0;
        rControlInput_U[2]          := 0.0;
        rControlInput_U[3]          := rHYDRAULIC_BASE_PRESS_BAR;

        IF bEmergencyStop THEN
            iState := 0; (* Return to State 0 After Reset *)
        END_IF;

    ELSE
        iState := 0; (* Defensive Default *)
END_CASE;

(*
 * ====================================================================================================
 * SECTION 7: ACTIVE TORQUE VECTORING (ATV) & 4-WHEEL ALLOCATION
 * ====================================================================================================
 *)
rTotalTractionForce_kN := rControlInput_U[0];
rTargetYawMoment_kNm   := rControlInput_U[1];

(* Allocate Total Longitudinal Force Proportionally to Dynamic Corner Normal Load *)
rForceDemand_FL_kN := (rTotalTractionForce_kN * (rDynamicNormLoad_FL_kN / rTotalNormalLoad_kN)) -
                      ((rTargetYawMoment_kNm / rVEHICLE_TRACKWIDTH_M) * (rDynamicNormLoad_FL_kN / rFrontAxleLoad_kN));
rForceDemand_FR_kN := (rTotalTractionForce_kN * (rDynamicNormLoad_FR_kN / rTotalNormalLoad_kN)) +
                      ((rTargetYawMoment_kNm / rVEHICLE_TRACKWIDTH_M) * (rDynamicNormLoad_FR_kN / rFrontAxleLoad_kN));
rForceDemand_RL_kN := (rTotalTractionForce_kN * (rDynamicNormLoad_RL_kN / rTotalNormalLoad_kN)) -
                      ((rTargetYawMoment_kNm / rVEHICLE_TRACKWIDTH_M) * (rDynamicNormLoad_RL_kN / rRearAxleLoad_kN));
rForceDemand_RR_kN := (rTotalTractionForce_kN * (rDynamicNormLoad_RR_kN / rTotalNormalLoad_kN)) +
                      ((rTargetYawMoment_kNm / rVEHICLE_TRACKWIDTH_M) * (rDynamicNormLoad_RR_kN / rRearAxleLoad_kN));

(* Apply Friction Circle / Adhesion Envelope Saturation *)
rForceDemand_FL_kN := LIMIT(-rAdhesionLimit_FL_kN, rForceDemand_FL_kN, rAdhesionLimit_FL_kN);
rForceDemand_FR_kN := LIMIT(-rAdhesionLimit_FR_kN, rForceDemand_FR_kN, rAdhesionLimit_FR_kN);
rForceDemand_RL_kN := LIMIT(-rAdhesionLimit_RL_kN, rForceDemand_RL_kN, rAdhesionLimit_RL_kN);
rForceDemand_RR_kN := LIMIT(-rAdhesionLimit_RR_kN, rForceDemand_RR_kN, rAdhesionLimit_RR_kN);

(* Convert Corner Tractive Forces to Wheel Hub Inverter Torque Demands: T = F * R_w *)
rRawTorque_FL_kNm := rForceDemand_FL_kN * rWHEEL_RADIUS_M;
rRawTorque_FR_kNm := rForceDemand_FR_kN * rWHEEL_RADIUS_M;
rRawTorque_RL_kNm := rForceDemand_RL_kN * rWHEEL_RADIUS_M;
rRawTorque_RR_kNm := rForceDemand_RR_kN * rWHEEL_RADIUS_M;

(* Slew-Rate Limiting of Torque Output Demands to Inverter Drives *)
rMaxCycleDelta := rTorqueRateLimit_kNmPerSec * rCycleTimeSec;

